define({"topics":[{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_32.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e133215","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_37.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e133318","topics":[]},{"title":"Replacing the leak sensors","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ReplacingTheLeakSensors.html","attributes":{"data-id":"id_2011319"},"menu":{"hasChildren":false},"tocID":"id_2011319-d46e133420","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_30.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e133521","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_33.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e133623","topics":[]},{"title":"Doing the leak sensor functional check","shortdesc":"<p class=\"shortdesc\">Follow this procedure to do the leak sensor functional check.<\/p>","href":"t_DoingTheLeakSensorFunctionalCheck_3.html","attributes":{"data-id":"id_2001881"},"menu":{"hasChildren":false},"tocID":"id_2001881-d46e133726","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_31.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e134438","topics":[]}]});